export const AGENT_NAMES = ['Claude Code', 'Codex', 'Cursor', 'GitHub Copilot', 'Gemini CLI', 'Windsurf', 'Cline', 'Replit', 'v0', 'Zed', 'JetBrains AI'];
export const APP_NAMES = ['Salesforce', 'HubSpot', 'Slack', 'Gmail', 'Zendesk', 'Notion', 'Jira', 'Stripe', 'Google Calendar', 'Asana', 'Shopify', 'Intercom', 'Trello', 'Airtable', 'Linear', 'Dropbox', 'QuickBooks', 'MailChimp', 'Typeform', 'Greenhouse'];
BRAND_ICONS.push(...MORE_CLUSTER_ICONS);
export const CLUSTER_APP_NAMES = APP_NAMES.concat(MORE_CLUSTER_ICONS.map((i) => i.n));

export function BrandIcon({ name, size = 24, className = '', forceColor }) {
    const icon = BRAND_ICONS.find((i) => i.n === name);
    if (!icon) return null;
    return (
        <svg viewBox="0 0 24 24" width={size} height={size} className={className} role="img" aria-label={icon.n}>
            <path d={icon.d} fill={forceColor || icon.c} />
        </svg>
    );
}

export function brandColor(name) {
    return BRAND_ICONS.find((i) => i.n === name)?.c || '#444';
}
